import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import Swal from "sweetalert2";

export default function ParentFeePage() {
  const [admissionNo, setAdmissionNo] = useState("");
  const [summary, setSummary] = useState(null);
  const [amount, setAmount] = useState("");
  const [structure, setStructure] = useState(null); // overall fee structure

  // Load overall school fee structure
  useEffect(() => {
    axios
      .get(`http://localhost:5000/api/fees?t=${Date.now()}`) // avoid cached 304
      .then((res) => {
        if (res.data.success) setStructure(res.data.data);
      })
      .catch(() => toast.error("Failed to load overall fee structure"));
  }, []);

  // Fetch individual student's fee
  const fetchFee = async () => {
    if (!admissionNo.trim()) return toast.error("Enter admission number");
    try {
      const res = await axios.get(
        `http://localhost:5000/api/fees/student/${admissionNo.trim()}`
      );
      if (res.data.success && res.data.data) {
        setSummary(res.data.data);
        toast.success("Fee record loaded!");
      } else {
        setSummary(null);
        toast.error("No record found!");
      }
    } catch {
      setSummary(null);
      toast.error("Failed to fetch student fee");
    }
  };

  // Simulated payment
  const payNow = async () => {
    const amt = Number(amount);
    if (!amt || amt <= 0) return toast.error("Enter a valid amount");

    const confirm = await Swal.fire({
      title: `Pay ₹${amt}?`,
      showCancelButton: true,
    });
    if (!confirm.isConfirmed) return;

    try {
      const res = await axios.post("http://localhost:5000/api/fees/pay", {
        admissionNo,
        amount: amt,
        method: "simulated",
      });

      if (res.data.success) {
        const updated = await axios.get(
          `http://localhost:5000/api/fees/student/${admissionNo}`
        );
        setSummary(updated.data.data);

        Swal.fire({
          icon: "success",
          title: "Payment Successful!",
          html: `
            <p><b>Amount Paid:</b> ₹${amt}</p>
            <p><b>Remaining Fee:</b> ₹${updated.data.data.fee.remaining}</p>
          `,
        });

        setAmount("");
      } else {
        toast.error(res.data.error || "Payment failed");
      }
    } catch {
      toast.error("Payment failed");
    }
  };

  // Helper to render fee categories
  const renderCategories = (fee) => {
    if (!fee?.categories) return null;

    return fee.categories.map((cat) => {
      const catTotal = cat.items.reduce((sum, i) => sum + (i.amount || 0), 0);
      return (
        <div key={cat.title} className="fee-category">
          <h4>{cat.title}</h4>
          <table className="fee-table">
            <thead>
              <tr>
                <th>Particulars</th>
                <th>Amount (₹)</th>
              </tr>
            </thead>
            <tbody>
              {cat.items.map((item) => (
                <tr key={item.key}>
                  <td>{item.title}</td>
                  <td>₹{item.amount}</td>
                </tr>
              ))}
              <tr>
                <td><b>Category Total</b></td>
                <td><b>₹{catTotal}</b></td>
              </tr>
            </tbody>
          </table>
        </div>
      );
    });
  };

  return (
    <div className="fee-page">
      <Toaster />

      {/* Overall Fee Structure */}
      {structure && (
        <div className="overall-structure">
          <h2>School Fee Structure ({structure.academicYear})</h2>
          <div dangerouslySetInnerHTML={{ __html: structure.notes }} />
          {renderCategories(structure)}

          {/* Overall total */}
          <p>
            <b>
              Overall Total: ₹
              {structure.categories
                .reduce(
                  (sum, cat) =>
                    sum + cat.items.reduce((s, i) => s + (i.amount || 0), 0),
                  0
                )
                .toLocaleString()}
            </b>
          </p>
        </div>
      )}

      {/* Admission Search */}
      <div className="search-box" style={{ marginTop: "30px" }}>
        <h3>💳 Pay School Fees</h3>
        <input
          type="text"
          value={admissionNo}
          onChange={(e) => setAdmissionNo(e.target.value)}
          placeholder="Enter Admission Number (e.g. KV-668272)"
        />
        <button onClick={fetchFee}>Search</button>
      </div>

      {/* Student Fee */}
      {summary && (
        <div className="fee-card">
          <h3>
            Fee Structure for {summary.student.studentName} (
            {summary.student.admissionNo})
          </h3>
          {renderCategories(summary.fee)}

          <table className="fee-table" style={{ marginTop: "10px" }}>
            <tbody>
              <tr>
                <td><b>Total</b></td>
                <td>₹{summary.fee.total}</td>
              </tr>
              <tr>
                <td>Paid</td>
                <td>₹{summary.fee.paid}</td>
              </tr>
              <tr>
                <td>Remaining</td>
                <td>₹{summary.fee.remaining}</td>
              </tr>
            </tbody>
          </table>

          {/* Payment Section */}
          <div className="pay-section" style={{ marginTop: "15px" }}>
            <input
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              placeholder="Enter amount to pay"
            />
            <button onClick={payNow}>Pay Now</button>
            <button
              onClick={() => setAmount(summary.fee.remaining)}
              style={{ marginLeft: "10px" }}
            >
              Pay Full
            </button>
          </div>
        </div>
      )}

      {!summary && (
        <p className="info-text">
          Enter admission number to view personal fee details.
        </p>
      )}
    </div>
  );
}



















